import csv
from io import StringIO

def f(text):
    reader = csv.reader(StringIO(text))
    try:
        next(reader)
    except StopIteration:
        return []

    result = []
    for row in reader:
        if not row:
            continue
        result.append((int(row[0]), row[1], float(row[2])))
    return result
