def f(nums):
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1

    seen = set()
    result = []
    for x in nums:
        if counts[x] > 1 and x not in seen:
            seen.add(x)
            result.append(x)

    return result
